import { cn } from '@components/lib/utils'
import { useSelectContext } from './context'
import type { SelectValueProps } from './types'

/**
 * 触发器内的当前值展示。
 *
 * 文案来源：`SelectItem` 挂载时通过 `register` 写入的 label Map。
 * 尚未选中（或对应项尚未注册）时显示 `placeholder`，再缺省则 `"Select"`。
 *
 * 有值用前景色，占位符用 muted，避免「看起来像已选中」。
 */
export function SelectValue({ placeholder, className }: SelectValueProps) {
  const ctx = useSelectContext('SelectValue')
  const label = ctx.labelFor(ctx.value)

  return (
    <span className={cn(label ? 'text-foreground' : 'text-muted-foreground', className)}>
      {label ?? placeholder ?? 'Select'}
    </span>
  )
}

// ===== SelectContent.tsx =====
import { useLayoutEffect, useRef, useState } from 'react'
import { motion } from 'motion/react'
import { EASE_OUT } from '@components/lib/select-ease'
import { cn } from '@components/lib/utils'
import { useSelectContext } from './context'
import {
  FLIP_SAFE_GAP,
  NEAR_GAP,
  gapTransition,
  initialTransition,
  listVariants,
} from './motion'
import type { SelectContentProps } from './types'

/**
 * 选项面板：绝对定位在触发器上方或下方，用 height 弹簧做展开 / 收起。
 *
 * ## 为何关闭后仍挂载 children
 * 打开只动画面板高度，不卸载 `SelectItem`。否则 `unregister` 会清掉 label，
 * 触发器上的 `SelectValue` 会在关闭瞬间掉回占位符。
 *
 * ## 翻转
 * 打开时量一次视口：下方放不下（高度 + 16px 安全距）且上方更宽裕 → `placement: 'top'`。
 *
 * ## 近侧 / 远侧
 * 朝向触发器的一侧叫近侧：打开时缝隙从 0→8。远侧 margin 为 0。
 * 两侧 margin 每次都写全，避免 `placement` 翻转后留下旧边距。
 * 圆角只走 className（默认 `rounded-xl`），不写 inline `border-radius`。
 *
 * ## 减少动态效果
 * 只做透明度和高度的短过渡，不做缝隙弹簧。
 */
export function SelectContent({ className, children }: SelectContentProps) {
  const ctx = useSelectContext('SelectContent')
  const innerRef = useRef<HTMLDivElement>(null)
  const [height, setHeight] = useState(0)
  const open = ctx.open
  const { setPlacement } = ctx

  useLayoutEffect(() => {
    const node = innerRef.current
    if (!node) return

    const measure = () => setHeight(node.offsetHeight)
    measure()

    const observer = new ResizeObserver(measure)
    observer.observe(node)
    return () => observer.disconnect()
  }, [])

  useLayoutEffect(() => {
    if (!open) return
    const trigger = document.getElementById(ctx.triggerId)
    const node = innerRef.current
    if (!trigger || !node) return

    const rect = trigger.getBoundingClientRect()
    const h = node.offsetHeight
    const below = window.innerHeight - rect.bottom
    const above = rect.top
    setPlacement?.(below < h + FLIP_SAFE_GAP && above > below ? 'top' : 'bottom')
  }, [open, ctx.triggerId, setPlacement])

  const isTop = ctx.placement === 'top'
  const nearGap = open ? NEAR_GAP : 0
  const gapT = gapTransition(open)

  const animate = ctx.reduce
    ? { opacity: open ? 1 : 0, height: open ? height : 0 }
    : {
        opacity: open ? 1 : 0,
        height: open ? height : 0,
        marginTop: isTop ? 0 : nearGap,
        marginBottom: isTop ? nearGap : 0,
      }

  const transition = ctx.reduce
    ? { duration: 0.12 }
    : {
        opacity: open ? { duration: 0.18 } : { duration: 0.16, delay: 0.12 },
        height: open
          ? { type: 'spring', duration: 0.42, bounce: 0.14 }
          : { duration: 0.26, ease: EASE_OUT, delay: 0.14 },
        marginTop: isTop ? initialTransition : gapT,
        marginBottom: isTop ? gapT : initialTransition,
      }

  return (
    <motion.div
      id={ctx.listId}
      role="listbox"
      aria-labelledby={ctx.triggerId}
      aria-hidden={!open}
      inert={!open}
      data-open={open}
      data-placement={ctx.placement}
      initial={false}
      animate={animate}
      transition={transition}
      style={{
        transformOrigin: isTop ? 'bottom' : 'top',
        overflow: 'hidden',
        pointerEvents: open ? 'auto' : 'none',
      }}
      className={cn(
        'absolute left-0 right-0 z-20 rounded-xl border border-border bg-background shadow-lg',
        isTop ? 'bottom-full' : 'top-full',
        className,
      )}
    >
      <motion.div
        ref={innerRef}
        variants={ctx.reduce ? undefined : listVariants}
        initial={false}
        animate={open ? 'show' : 'hidden'}
        className="p-1"
      >
        {children}
      </motion.div>
    </motion.div>
  )
}

// ===== SelectItem.tsx =====
import { useLayoutEffect } from 'react'
import { Check } from 'lucide-react'
import { motion } from 'motion/react'
import { cn } from '@components/lib/utils'
import { useSelectContext } from './context'
import { itemVariants } from './motion'
import type { SelectItemProps } from './types'

/**
 * 列表中的一项。
 *
 * ## 标签登记
 * 在 layout effect 里把 `value → label` 登记到根组件。
 * `children` 为字符串时用它做 label（触发器展示更友好）；否则用 `value`。
 *
 * 依赖里只列 `register` / `unregister` 引用（根组件用 `useCallback` 固定），
 * 避免把整个 context 对象放进依赖导致每次父渲染都重新登记。
 *
 * ## 无障碍
 * 外层是 `motion.li` 以配合 listbox；真正可聚焦的是内部 `role="option"` 按钮。
 * 选中项展示勾选图标，并用 `aria-selected` 同步给辅助技术。
 */
export function SelectItem({ value, disabled, className, children }: SelectItemProps) {
  const ctx = useSelectContext('SelectItem')
  const selected = ctx.value === value
  const label = typeof children === 'string' ? children : value

  useLayoutEffect(() => {
    ctx.register(value, label)
    return () => {
      ctx.unregister(value)
    }
  }, [ctx.register, ctx.unregister, value, label])

  return (
    <motion.li variants={ctx.reduce ? undefined : itemVariants}>
      <button
        type="button"
        role="option"
        aria-selected={selected}
        disabled={disabled}
        onClick={() => ctx.select(value)}
        className={cn(
          'flex w-full items-center justify-between gap-2 rounded-lg px-2.5 py-1.5 text-left text-sm outline-none transition-colors',
          selected
            ? 'bg-muted text-foreground'
            : 'text-muted-foreground hover:bg-muted hover:text-foreground focus-visible:bg-muted',
          'disabled:pointer-events-none disabled:opacity-50',
          className,
        )}
      >
        {children}
        {selected && <Check className="w-4 h-4" />}
      </button>
    </motion.li>
  )
}
